import React, { useState } from 'react';
import { motion } from 'framer-motion';

/**
 * CharacterSelect Component
 * 
 * 动效与交互优化：
 * 1. 【原版背景光逻辑 + 角色专属光照契合】：
 *    - Panel 0 (机车男): 契合车库顶棚聚光灯，释放冷白银蓝背景光 (rgba(195, 220, 255, 0.80))
 *    - Panel 1 (手机少女): 契合夜间卧室烛火与手机夜幕，释放柔和薄暮粉紫背景光 (rgba(235, 130, 185, 0.80))
 *    - Panel 2 (秋千少女): 契合秋千顶上醇厚金黄路灯，释放温润金黄暖光 (rgba(245, 185, 55, 0.85))
 *    - Panel 3 (耳机男): 契合音乐工作室壁炉火光与暖灯，释放温暖壁炉琥珀光 (rgba(195, 220, 255, 0.85))
 * 2. 【去除突兀两侧白边】：画格边框回归原版纯正深色黑描边，彻底移除生硬高亮白线条。
 * 3. 【全员不置灰】：未选中的角色保持 100% 原始色彩与饱和度（opacity: 1.0, filter: none），绝不强行压暗。
 * 4. 【选男/选女随机高亮对应角色】：
 *    - 点击「Male」：从机车男与耳机男中随机点亮一名，再次点击切换至另一名。
 *    - 点击「Female」：从手机少女与秋千少女中随机点亮一名，再次点击切换至另一名。
 *    - 点击「Non-binary」：选项按钮激活，所有角色保持自然原态不亮背景光。
 *    - 点击任意角色立绘：精准直达对应角色并联动其对应性别按钮。
 * 5. 【紫色气泡匀速浮升】：仅保留原图 24 颗紫色粒子，严格匀速上升后渐隐消散。
 */
