                <motion.g custom={0} variants={bgVariants} initial="initial" animate="animate">
                  <rect x="-130.075" y="12.5" width="569.148" height="318.414" fill="url(#pattern0_8561_21847)" />
                  <path opacity="0.22" d="M736.795 -29.9141H2.93677V380.648H736.795V-29.9141Z" fill="#101A24" fill-opacity="0.18" />
                </motion.g>
                <motion.g
